import os, re, json

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), {k:(len(v),len(v[0])) for k,v in G.items()})

def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    bg = max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    def nbrs(r,c):
        return [(rr,cc) for rr in range(H) for cc in range(W)
                if (rr,cc)!=(r,c) and abs(rr-r)<=1 and abs(cc-c)<=1 and g[rr][cc]!=bg]
    deg={p:len(nbrs(*p)) for p in cells}
    for p in cells:
        if deg[p]==1:
            n=nbrs(*p)[0]
            dr,dc=p[0]-n[0],p[1]-n[1]
            r,c=p[0]+dr,p[1]+dc
            while 0<=r<H and 0<=c<W:
                g[r][c]=g[p[0]][p[1]]; r+=dr; c+=dc
    return g

for k in ['Demo pair 1 input','Demo pair 2 input']:
    out=transform(G[k])
    exp=G[k.replace('input','output')]
    print(k, out==exp)
print(json.dumps(transform(G['Test input'])))
